const listOverdueAccessRequests = `-- name: ListOverdueAccessRequests :many
SELECT ar.id, ar.principal, ar.kind, ar.workspace, ar.verified, ar.server, s.session_id
FROM access_requests ar
LEFT JOIN sessions s ON s.id = ar.session_pk
WHERE ar.status = 'pending' AND ar.expires_at < now() - $1::interval
ORDER BY ar.expires_at
LIMIT 1000
`

type ListOverdueAccessRequestsRow struct {
	ID        string
	Principal string
	Kind      string
	Workspace string
	Verified  bool
	Server    pgtype.Text
	SessionID pgtype.Text
}

// Lists pending access requests whose expires_at is more than grace past,
// for the leader's pass.
func (q *Queries) ListOverdueAccessRequests(ctx context.Context, grace pgtype.Interval) ([]ListOverdueAccessRequestsRow, error) {
	rows, err := q.db.Query(ctx, listOverdueAccessRequests, grace)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOverdueAccessRequestsRow{}
	for rows.Next() {
		var i ListOverdueAccessRequestsRow
		if err := rows.Scan(
			&i.ID,
			&i.Principal,
			&i.Kind,
			&i.Workspace,
			&i.Verified,
			&i.Server,
			&i.SessionID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

