const lockPrincipalAccessRequests = `-- name: LockPrincipalAccessRequests :exec
SELECT pg_advisory_xact_lock(hashtextextended('toolgate-access-request/' || $1::text, 0))
`

// Takes the transaction advisory lock that serializes access-request
// inserts for one principal. It is separate from the approvals lock.
func (q *Queries) LockPrincipalAccessRequests(ctx context.Context, principal string) error {
	_, err := q.db.Exec(ctx, lockPrincipalAccessRequests, principal)
	return err
}

const lockUserScope = `-- name: LockUserScope :one
SELECT id, principal, verified_default, unverified_default, updated_at, unverified_list FROM user_scopes WHERE principal = $1 FOR UPDATE
`

